func testDigest(raw []byte) string {
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

// Every response here is generated by a test, not collected from a real model.
// The real-kind branch exercises the LOCAL human-audit boundary only; the test
// policy deliberately accepts wide CIs and is not a deployment recommendation.
func admissionFixture(t *testing.T, kind attribution.DatasetKind) (bankTransfer, []string) {
	t.Helper()
	challenges := fingerprint.DefaultChallenges()
	for i := range challenges {
		challenges[i].Parameters = map[string]any{"stream": false, "max_tokens": MaxOutputTokens}
	}
	c := attribution.Corpus{SchemaVersion: 1, AlgorithmVersion: fingerprint.AlgorithmVersion, Kind: kind,
		SystemPromptSHA256: testDigest(nil), Challenges: challenges}
	ids := []string{}
	for n, split := range []attribution.Split{attribution.Reference, attribution.Calibration, attribution.Test, attribution.UnknownTest, attribution.ChannelHoldout, attribution.TimeHoldout} {
		models := []struct {
			id, family, value string
		}{{"fixture-A", "fixture-family-A", "17"}, {"fixture-B", "fixture-family-B", "355"}}
		if split == attribution.Calibration {
			models = append(models, struct{ id, family, value string }{"fixture-cal-unknown", "fixture-unknown", "173"})
		}
		if split == attribution.UnknownTest {
			models = []struct{ id, family, value string }{{"fixture-test-unknown", "fixture-unknown", "211"}}
		}
		if split == attribution.ChannelHoldout || split == attribution.TimeHoldout {
			models = append(models, struct{ id, family, value string }{fmt.Sprintf("fixture-unknown-%d", n), "fixture-unknown", "211"})
		}
		channel := "channel"
		if split == attribution.ChannelHoldout {
			channel = "held-fixture-channel"
		}
		date := time.Now().UTC().AddDate(0, 0, n-5).Format(time.RFC3339Nano)
		for _, model := range models {
			group := string(split) + "-" + model.id
			for _, ch := range challenges {
				id := group + "-" + ch.ID
				ids = append(ids, id)
				answer := strings.TrimSuffix(strings.Repeat(model.value+",", ch.Count), ",")
				parameters, _ := json.Marshal(ch.Parameters)
				evidence := json.RawMessage(`{"test_fixture":"generated; no actual model observation"}`)
				source := "synthetic"
				if kind == attribution.Real {
					source = "manual_import"
				}
				c.Records = append(c.Records, attribution.Record{ID: id, GroupID: group, BatchID: "batch-" + group, SessionID: "session-" + group,
					Split: split, Model: model.id, Family: model.family, Channel: channel, CollectedAt: date, SourceType: source,
					ChallengeID: ch.ID, RawResponse: answer, ResponseSHA256: testDigest([]byte(answer)), FinishReason: "stop", RequestID: "request-" + id,
					RequestParameters: parameters, SystemPromptSHA256: c.SystemPromptSHA256,
					LabelEvidence: evidence, LabelEvidenceSHA256: testDigest(evidence), RouteEvidence: evidence, RouteEvidenceSHA256: testDigest(evidence)})
			}
		}
	}
	corpus, err := json.Marshal(c)
	if err != nil {
		t.Fatal(err)
	}
	manifest, err := attribution.MarshalBank(corpus, "admission-fixture-v1", []attribution.Model{{ID: "fixture-A", Family: "fixture-family-A"}, {ID: "fixture-B", Family: "fixture-family-B"}})
	if err != nil {
		t.Fatal(err)
	}
	bundle, err := attribution.MarshalBundle(manifest, corpus)
	if err != nil {
		t.Fatal(err)
	}
	return bankTransfer{Bank: modelstore.Bank{ID: "admission-fixture", Version: "admission-fixture-v1", AlgorithmVersion: fingerprint.AlgorithmVersion,
		ChallengeVersion: ChallengeVersion, SourceType: "manual_import", Provenance: "Generated admission boundary fixture; not real model evidence", Trusted: true,
		ModelCount: 999, SampleCount: 999, ValidationMetrics: map[string]any{"identity_validated": true, "independent_validation": true}}, Data: string(bundle)}, ids
}

func sendBank(t *testing.T, server *httptest.Server, transfer bankTransfer) {
	t.Helper()
	raw, _ := json.Marshal(transfer)
	r := apiRequest(t, server, "POST", "/api/banks", string(raw), "page-session", "null")
	if r.StatusCode != 201 {
		t.Fatal(r.StatusCode)
	}
}

func TestReferenceImportRecomputesAndKeepsAuditingSeparate(t *testing.T) {
	s := testService(t, http.NotFoundHandler())
	server := management(t, s)
	transfer, ids := admissionFixture(t, attribution.Synthetic)
	sendBank(t, server, transfer)
	r := apiRequest(t, server, "GET", "/api/banks/admission-fixture", "", "page-session", "null")
	if r.StatusCode != 200 {
		t.Fatalf("reference inspection endpoint: %d", r.StatusCode)
	}
	var detail struct {
		Bank       modelstore.Bank              `json:"bank"`
		Validation attribution.ValidationReport `json:"validation"`
		Provenance []attribution.Binding        `json:"provenance"`
	}
	if err := json.NewDecoder(r.Body).Decode(&detail); err != nil {
		t.Fatal(err)
	}
	if detail.Bank.Trusted || detail.Validation.IdentityValidated || !detail.Validation.IntegrityValidated || detail.Validation.ProvenanceValidated {
		t.Fatal("imported trust flag or synthetic labels became audited", detail.Validation)
	}
	if detail.Bank.ModelCount != 2 || detail.Bank.SampleCount != len(ids) || len(detail.Provenance) != len(ids) {
		t.Fatal("counts were not recomputed from bound raw records")
	}
	metric := detail.Validation.BySplit[attribution.Test].Top1Accuracy
	if metric.Total != 2 || metric.Value == nil || metric.Interval != nil || detail.Validation.BySplit[attribution.Test].BrierScore != nil {
		t.Fatal("grouped counts missing or confidence/probability invented without an explicit experiment policy")
	}
}

func TestReferenceImportRejectsCredentialsInsideRawBundleStrings(t *testing.T) {
	s := testService(t, http.NotFoundHandler())
	server := management(t, s)
	for _, raw := range []string{
		`{"nested":"{\"authorization\":\"Bearer leaked-secret\"}"}`,
		`{"unknown":"Bearer fixture-only-value"}`,
		`{"nested":"{\"password\":\"leaked\"}"}`,
	} {
		transfer := bankTransfer{Bank: modelstore.Bank{Version: "credential-fixture", AlgorithmVersion: fingerprint.AlgorithmVersion, ChallengeVersion: ChallengeVersion,
			SourceType: "manual_import", Provenance: "Credential regression fixture"}, Data: raw}
		data, _ := json.Marshal(transfer)
		r := apiRequest(t, server, "POST", "/api/banks", string(data), "page-session", "null")
		if r.StatusCode != 422 {
			t.Fatalf("nested credential accepted: status=%d", r.StatusCode)
		}
	}
}

type referenceDetailForTest struct {
	Bank               modelstore.Bank              `json:"bank"`
	Validation         attribution.ValidationReport `json:"validation"`
	Provenance         []attribution.Binding        `json:"provenance"`
	ProvenanceSHA256   string                       `json:"provenance_sha256"`
	ProtocolCompatible bool                         `json:"protocol_compatible"`
}

func readReference(t *testing.T, server *httptest.Server) referenceDetailForTest {
	t.Helper()
	r := apiRequest(t, server, "GET", "/api/banks/admission-fixture", "", "page-session", "null")
	var detail referenceDetailForTest
	if r.StatusCode != 200 || json.NewDecoder(r.Body).Decode(&detail) != nil {
		t.Fatal("reference inspection failed", r.StatusCode)
	}
	return detail
}

func testReviewBody(detail referenceDetailForTest, ids []string) map[string]any {
	return map[string]any{"bank_sha256": detail.Bank.SHA256, "corpus_sha256": detail.Validation.CorpusSHA256,
		"provenance_sha256": detail.ProvenanceSHA256, "reviewer": "local-test-auditor", "review_note": "Generated audit-boundary unit test, not a model identity experiment",
		"confirm_independent_source_review": true, "approved_record_ids": ids,
		"policy": attribution.Policy{Confidence: 0.95, MaxFalseMatchRate: 1, MaxFalseReplacementRate: 1, MinUnknownRecall: 0,
			MaxKnownRejectionRate: 1, MinTop1Accuracy: 0, MinFamilyAccuracy: 0}}
}

func approveReference(t *testing.T, server *httptest.Server, ids []string) referenceDetailForTest {
	t.Helper()
	detail := readReference(t, server)
	data, _ := json.Marshal(testReviewBody(detail, ids))
	r := apiRequest(t, server, "POST", "/api/banks/admission-fixture/review", string(data), "page-session", "null")
	if r.StatusCode != 200 {
		t.Fatalf("local audit not saved: %d", r.StatusCode)
	}
	return readReference(t, server)
}

func TestReferenceReviewRequiresExactHashesAllRecordsAndHumanAcknowledgement(t *testing.T) {
	s := testService(t, http.NotFoundHandler())
	server := management(t, s)
	transfer, ids := admissionFixture(t, attribution.Real)
	sendBank(t, server, transfer)
	detail := readReference(t, server)
	for _, field := range []string{"bank_sha256", "corpus_sha256", "provenance_sha256", "approved_record_ids", "confirm_independent_source_review", "policy"} {
		input := testReviewBody(detail, ids)
		input[field] = nil
		data, _ := json.Marshal(input)
		r := apiRequest(t, server, "POST", "/api/banks/admission-fixture/review", string(data), "page-session", "null")
		if r.StatusCode != 422 && r.StatusCode != 409 {
			t.Fatalf("incomplete audit %s accepted: %d", field, r.StatusCode)
		}
	}
	detail = approveReference(t, server, ids)
	if !detail.Validation.ProvenanceValidated || !detail.Validation.IdentityValidated || !detail.Bank.Trusted || !detail.ProtocolCompatible {
		t.Fatal("explicit bound audit and permissive TEST policy were not recomputed", detail.Validation)
	}
	if detail.Validation.BySplit[attribution.Test].Top1Accuracy.Interval == nil || detail.Validation.BySplit[attribution.Test].BrierScore != nil {
		t.Fatal("explicit confidence interval missing or probability invented")
	}
}

func TestSyntheticReferenceCannotBeSourceApprovedOrActivated(t *testing.T) {
	s := testService(t, http.NotFoundHandler())
	server := management(t, s)
	transfer, ids := admissionFixture(t, attribution.Synthetic)
	sendBank(t, server, transfer)
	detail := readReference(t, server)
	data, _ := json.Marshal(testReviewBody(detail, ids))
	r := apiRequest(t, server, "POST", "/api/banks/admission-fixture/review", string(data), "page-session", "null")
	if r.StatusCode != 409 {
		t.Fatal("synthetic audit was accepted", r.StatusCode)
	}
	r = apiRequest(t, server, "POST", "/api/banks/admission-fixture/activate", `{}`, "page-session", "null")
	if r.StatusCode != 409 {
		t.Fatal("synthetic reference was activated", r.StatusCode)
	}
}

func TestLocalReferenceReviewPersistsButDoesNotTravelWithBackup(t *testing.T) {
	dir := t.TempDir()
	s, err := New(dir, Config{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(s.Close)
	server := management(t, s)
	transfer, ids := admissionFixture(t, attribution.Real)
	sendBank(t, server, transfer)
	approveReference(t, server, ids)
	r := apiRequest(t, server, "POST", "/api/banks/admission-fixture/activate", `{}`, "page-session", "null")
	if r.StatusCode != 200 {
		t.Fatal("reviewed compatible reference was not activated", r.StatusCode)
	}
	backup, err := s.store.Export()
	if err != nil {
		t.Fatal(err)
	}
	s.Close()
	reopened, err := New(dir, Config{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(reopened.Close)
	reopenedServer := management(t, reopened)
	if !readReference(t, reopenedServer).Validation.IdentityValidated {
		t.Fatal("authenticated local review disappeared after restart")
	}
	key, err := os.ReadFile(filepath.Join(dir, "reference-review.key"))
	if err != nil || len(key) != 32 || strings.Contains(string(backup), hex.EncodeToString(key)) {
		t.Fatal("private audit key was absent or exported", err)
	}
	for _, receiver := range []*Service{reopened, testService(t, http.NotFoundHandler())} {
		receiverServer := management(t, receiver)
		r := apiRequest(t, receiverServer, "POST", "/api/restore", string(backup), "page-session", "null")
		if r.StatusCode != 200 {
			t.Fatal("restore failed", r.StatusCode)
		}
		if readReference(t, receiverServer).Validation.IdentityValidated || readReference(t, receiverServer).Bank.Trusted {
			t.Fatal("backup restored a trusted flag without a new local source review")
		}
	}
}

func TestReviewedReferenceNeedsExactProtocolAndStableCompleteRounds(t *testing.T) {
	for _, tc := range []struct {
		name, want, value string
		guard             bool
		version, budget   int
		changeRound       bool
		changePacket      bool
	}{
		{name: "matched", want: "MATCHED", value: "17", guard: true, version: 2, budget: 6},
		{name: "replaced", want: "MISMATCHED", value: "355", guard: true, version: 2, budget: 3},
		{name: "unknown", want: "UNKNOWN", value: "211", guard: true, version: 2, budget: 3},
		{name: "observer_not_final", want: "INCONCLUSIVE", value: "17", version: 2, budget: 3},
		{name: "route_only_v1", want: "INCONCLUSIVE", value: "17", guard: true, version: 1, budget: 3},
		{name: "inconsistent_rounds", want: "INCONCLUSIVE", value: "17", guard: true, version: 2, budget: 6, changeRound: true},
		{name: "incomplete_round", want: "INCONCLUSIVE", value: "17", guard: true, version: 2, budget: 2},
		{name: "mutated_sent_packet", want: "INCONCLUSIVE", value: "17", guard: true, version: 2, budget: 3, changePacket: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			calls := 0
			s := testService(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				var packet map[string]any
				json.NewDecoder(r.Body).Decode(&packet)
				messages := packet["messages"].([]any)
				prompt := messages[0].(map[string]any)["content"].(string)
				count := 0
				for _, ch := range fingerprint.DefaultChallenges() {
					if ch.Prompt == prompt {
						count = ch.Count
					}
				}
				value := tc.value
				if tc.changeRound && calls >= 3 {
					value = "355"
				}
				calls++
				content := strings.TrimSuffix(strings.Repeat(value+",", count), ",")
				id := packet["_magpie_model_check_probe"].(map[string]any)["id"].(string)
				route := signedRoute(strings.Repeat("a", 64), id, "channel/solo", "channel", content, "stop")
				route.Version = tc.version
				if tc.changePacket {
					packet["max_tokens"] = 1024
				}
				if tc.version == 2 {
					route.RequestSHA256 = requestBodySHA256(packet)
				}
				mac := hmac.New(sha256.New, []byte(strings.Repeat("a", 64)))
				mac.Write([]byte(route.payload()))
				route.MAC = hex.EncodeToString(mac.Sum(nil))
				json.NewEncoder(w).Encode(map[string]any{"model": "untrusted-self-label", "choices": []any{map[string]any{"message": map[string]string{"content": content}, "finish_reason": "stop"}}, "_magpie_model_check_route": route})
			}))
			s.config.ProtocolGuard = tc.guard
			server := management(t, s)
			transfer, ids := admissionFixture(t, attribution.Real)
			sendBank(t, server, transfer)
			approveReference(t, server, ids)
			r := apiRequest(t, server, "POST", "/api/banks/admission-fixture/activate", `{}`, "page-session", "null")
			if r.StatusCode != 200 {
				t.Fatal("activation failed", r.StatusCode)
			}
			target := addTestTarget(t, s)
			target.ClaimedModel, target.RequestBudget = "fixture-A", tc.budget
			target, err := s.store.PutTarget(target)
			if err != nil {
				t.Fatal(err)
			}
			id, err := s.StartCheck(target.ID)
			if err != nil {
				t.Fatal(err)
			}
			result := waitBatch(t, s, id)
			if result.IdentityStatus != tc.want || result.CalibratedProbability != nil {
				t.Fatalf("got %s, wanted %s: %s", result.IdentityStatus, tc.want, result.RejectionReason)
			}
			if result.BankVersion != transfer.Version || result.Metrics["collection_protocol_sha256"] != collectionProtocolSHA256() {
				t.Fatal("batch did not snapshot reference version and independently computed collection protocol")
			}
			if tc.want == "INCONCLUSIVE" && (result.PredictedModel != "" || result.PredictedFamily != "") {
				t.Fatal("incomplete protocol or inconsistent rounds produced an identity")
			}
		})
	}
}
